draw((0,12)--(3,6)); [/asy]

일반성을 잃지 않고 정육각형의 변의 길이를 1 단위라고 가정합니다. 또한 제거된 이등변삼각형의 각 변의 길이를 $u$라고 합시다. 그림과 같이 점 $A$, $B$, $C$, $D$, $E$, $F$를 정의합니다. 삼각형 $CDB$는 30-60-90 삼각형이므로 $CD=u/2$이고 $DB=u\sqrt{3}/2$입니다. 또한 $CF=1$이고 $CB=AF=u$이기 때문에 $AB=1-2u$입니다. 결과 정십이각형이 정다각형이 되려면 $AB=2\cdot BD$여야 합니다. 다음을 얻습니다. \begin{align*}
1-2u&=u\sqrt{3} \implies \\
1&=2u+u\sqrt{3} \implies \\
1&=u(2+\sqrt{3}) \implies \\
\frac{1}{2+\sqrt{3}}&=u.
\end{align*} 분모의 유리화를 위해 분모와 분자에 $2-\sqrt{3}$을 곱하면 $u=2-\sqrt{3}$을 얻습니다. 변의 길이가 $s$인 정육각형의 면적은 $3s^2\sqrt{3}/2$이므로 정육각형의 면적은 $3\sqrt{3}/2$입니다. 제거된 면적은 $6\times \frac{1}{2}(CD)(2\cdot BD)=3u^2\sqrt{3}/2$입니다. 따라서 제거된 면적의 비율은 $u^2$이며, 이는 백분율로 소수점 첫째 자리까지 반올림하면 $0.072=\boxed{7.2\%}$입니다. [asy]
size(250);
real r = sqrt(6-3*sqrt(3));
pair A=r*dir(15), B=r*dir(45), C=dir(60), D=sqrt(3)/2*dir(60), Ep=(0,0), F=dir(0);
pair[] dots = {A,B,C,D,Ep,F};
dot(dots);
label("$A$",A,A);
label("$B$",B,B);
label("$C$",C,C);
label("$D$",D,1.6*(W+0.3*SW));
label("$E$",Ep,SW);
label("$F$",F,E);
int i;
for(i=0;i<=5;++i)

{

draw(dir(60*i)--dir(60*(i+1)));

}
for(i=0;i<=11;++i)

{

draw(r*dir(15+30*i)--r*dir(15+30*(i+1)));

}

draw((0,0)--dir(60));
label("$u$",dir(60)+0.12*SE);
label("$1-2u$",dir(30));[/asy]

