solution_ko:
정사영 $\mathbf{P}$는 $\begin{pmatrix} x \\ y \\ z \end{pmatrix}$를 $\begin{pmatrix} 0 \\ y \\ z \end{pmatrix}$로 변환합니다.

[asy]
import three;

size(180);
currentprojection = perspective(6,3,2);

triple I = (1,0,0), J = (0,1,0), K = (0,0,1), O = (0,0,0);
triple V = (2.2,2.5,2.5), W = (0,2.5,2.5);

draw(V--W,dashed);
draw(O--V, red, Arrow3(6));
draw(O--W,blue, Arrow3(6));
draw(O--3*I, Arrow3(6));
draw(O--3*J, Arrow3(6));
draw(O--3*K, Arrow3(6));

